import {distribution,categoryColor,categoryAppearance,layerNames,UNKNOWN,categories} from './layers.mjs';
import {nivel} from './level.mjs';
import {hojaConAlturas} from './hoja-alturas.mjs';
export function createPlanFilters(ctx){
 const root=document.getElementById('planFilters'),button=document.getElementById('planSettingsOpen'),esc=ctx.esc;
 let opened=false,categoryQuery='';
 // Celular: el panel sube desde abajo con tres alturas y abre bajo (búsqueda y especialidad, con el plano a la vista).
 const alturas=hojaConAlturas(root,{alturas:{baja:a=>a*.42,media:a=>a*.66,completa:a=>a},inicial:'baja',activa:()=>opened&&document.body.classList.contains('terreno')&&innerWidth<=700,alto:()=>innerHeight-54-64-16,alBajar:()=>close(),etiqueta:'Arrastra hacia arriba para ver más filtros o hacia abajo para cerrar'});
 const normalized=value=>String(value).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLocaleLowerCase('es');
 const families=[['walls','Muros'],['PAV','Pavimentos'],['CIE','Cielos'],['avance','Avance de obra'],['observaciones','Observaciones en terreno'],['asepsis','Asepsia'],['paint','Pinturas'],['sector','Sectores'],['status','Estado de revisión']];
 // Filtros y capas en un solo panel: especialidad del plano, capas del dibujo y textos sobre el plano. Las especialidades
 // siguen en su barra (disciplines.mjs), que queda oculta en Arquitectura: aquí se pulsan sus mismos botones.
 const tiposPlano=()=>[...document.querySelectorAll('.planTypes [data-plan-type]')];
 const textosPlano=[['layerCodes','Códigos de recinto'],['layerNames','Nombres de recinto']];
 // Rework 2026-11-22: «Plano» (uno a la vez, desactivado con el motivo si al piso le falta), su «Simbología» interactiva
 // (casillas por categoría con recintos y m²; al marcar, el plano destaca esos recintos y atenúa el resto) y «Sobre el
 // plano» (avance, observaciones, sectores, capas del dibujo y textos).
 const PLANOS=[['architecture','Arquitectura'],['ceilings','Cielos'],['floors','Pavimentos'],['fire','Compartimentación'],['walls','Muros'],['doors','Puertas'],['waterproofing','Impermeabilización']];
 const FALTA={ceilings:'Falta el plano de Cielos',floors:'Falta el plano de Pavimentos',fire:'Falta el plano de Compartimentación',doors:'Falta el plano de Puertas',waterproofing:'Falta la lámina IMP'};
 const planoActual=()=>document.body.classList.contains('puertasOpen')?'doors':document.querySelector('.planTypes [aria-pressed=true]')?.dataset.planType||'architecture';
 // Familia de colores que hace de simbología de cada plano (null: el plano no trae datos por recinto).
 const familiaDe=plano=>plano==='ceilings'?(nivel.especialidades?'CIE':'cielosLamina'):plano==='floors'?'PAV':plano==='walls'?'walls':plano==='architecture'?undefined:null;
 const areaDe=r=>{const v=parseFloat(String(r?.declared_area??'').replace(/m(²|2)/,'').replace(/\./g,'').replace(',','.'));return Number.isFinite(v)?v:0;};
 function superficies(type){const m=new Map();for(const r of ctx.all()){const a=areaDe(r);for(const k of categories(r,type))m.set(k,(m.get(k)||0)+a);}return m;}
 const m2=v=>v?v.toLocaleString('es-CL',{maximumFractionDigits:0})+' m²':'';
 function seccionPlanos(){const hay=new Set(tiposPlano().map(b=>b.dataset.planType)),actual=planoActual();
  return `<h3 class="filterSeccion">Plano</h3><div class="filterPlanos" role="radiogroup" aria-label="Plano">${PLANOS.map(([k,n])=>hay.has(k)
   ?`<button type="button" role="radio" data-plano="${k}" aria-checked="${k===actual}">${esc(n)}</button>`
   :`<button type="button" role="radio" aria-checked="false" disabled title="${esc(FALTA[k]||'')}">${esc(n)}<small>${esc(FALTA[k]||'')}</small></button>`).join('')}</div>`;}
 function seccionSobre(){const {active,enabled}=ctx.state(),resto=seccionPlano().replace(/^[\s\S]*?<div class="filterCapas">/,'');
  return `<h3 class="filterSeccion">Sobre el plano</h3><div class="filterCapas">${[['avance','Avance de obra'],['observaciones','Observaciones en terreno'],['sector','Sectores']].map(([k,n])=>`<label class="check"><input type="checkbox" data-sobre="${k}" ${enabled&&active===k?'checked':''}> ${n}</label>`).join('')}${resto}`;}
 function seccionPlano(){const capas=ctx.capas?.()||[];return `<h3 class="filterSeccion">Especialidad</h3><div class="filterTiposPlano">${tiposPlano().map(b=>`<button type="button" data-tipo-plano="${esc(b.dataset.planType)}" aria-pressed="${b.getAttribute('aria-pressed')}" ${b.disabled?'disabled':''}>${esc(b.firstChild.textContent)}</button>`).join('')}</div><h3 class="filterSeccion">Capas</h3><div class="filterCapas">${capas.map(c=>`<label class="check"><input type="checkbox" data-capa="${esc(c.id)}" ${c.visible?'checked':''}> ${esc(c.nombre)}</label>`).join('')}${textosPlano.map(([id,nombre])=>`<label class="check"><input type="checkbox" data-texto-plano="${id}" ${document.getElementById(id)?.checked?'checked':''}> ${nombre}</label>`).join('')}</div>${capas.length?'':'<small class="filterHelp">Este plano viene de PDF sin capas: mobiliario, ejes y relleno se podrán apagar cuando se carguen sus láminas DWG.</small>'}<h3 class="filterSeccion">Filtros</h3>`;}
 function close(focus=false){if(!opened)return;opened=false;root.hidden=true;document.body.classList.remove('filtersOpen');button.setAttribute('aria-expanded','false');if(focus)button.focus();ctx.resize();}
 function open(opciones={}){if(ctx.editing())return ctx.toast('Guarda o cancela el contorno antes de abrir los filtros.');ctx.enter();opened=true;root.hidden=false;document.body.classList.add('filtersOpen');document.body.classList.add('hideRight','hideLeft');button.setAttribute('aria-expanded','true');render();alturas.fijar('media');ctx.resize();if(opciones.simbologia)root.querySelector('[data-simbologia]')?.scrollIntoView({block:'start'});else if(!document.body.classList.contains('terreno'))root.querySelector('#planFilterSearch').focus({preventScroll:true});}
 function update(){if(!opened)return;root.querySelector('#planFilterCount').textContent=ctx.rows().length+' de '+ctx.all().length+' recintos';const input=root.querySelector('#planFilterSearch');if(document.activeElement!==input)input.value=ctx.query();}
 function render(){
  const focused=document.activeElement,focusId=root.contains(focused)?focused.id:null,focusKey=root.contains(focused)?focused.dataset.filter:null;
  const plano=planoActual(),simbologia=familiaDe(plano);if(simbologia&&ctx.state().active!==simbologia&&!['avance','observaciones','sector'].includes(ctx.state().active))ctx.change({active:simbologia,enabled:true},false);
  const {active,filters,enabled,colors}=ctx.state(),sup=superficies(active),scroll=root.querySelector('.planFilterBody')?.scrollTop||0,scrollHoja=root.scrollTop;
  const note=active==='observaciones'?'Recintos según sus observaciones en terreno: con vencidas, abiertas, corregidas por verificar o cerradas (registros de este equipo).':active==='avance'?'Estado del recinto según el avance valorizado por partida (registros de este dispositivo).':active==='CIE'?'Todos los tipos de cielo parten marcados. Desmarca los que no quieras ver.':'Todos los tipos parten marcados. Desmarca los que no quieras ver; con «Ninguno» y una casilla ves solo ese tipo.';
  root.innerHTML=`<div class="planFilterHead"><div><span class="section-label">HERRAMIENTAS DEL PLANO</span><h2 id="planFiltersTitle">Filtros y capas</h2></div><button id="closePlanFilters" aria-label="Cerrar filtros y capas">×</button></div><div class="planFilterBody"><label for="planFilterSearch">Código, recinto o terminación</label><input id="planFilterSearch" type="search" placeholder="Buscar en este piso…" value="${esc(ctx.query())}" autocomplete="off"><p id="planFilterCount" role="status"></p>${seccionPlanos()}<section class="filterSimbologia" data-simbologia ${simbologia===null?'data-sin-datos':''}><h3 class="filterSeccion">Simbología · ${esc(PLANOS.find(([k])=>k===plano)?.[1]||'Arquitectura')}</h3><p class="simbologiaNota">${simbologia===null?'Este plano no trae datos por recinto para marcar.':'Marca categorías para destacar esos recintos en el plano.'}</p><div class="filterChips">${Object.entries(filters).filter(([type])=>type!==active).flatMap(([type,keys])=>keys.map(key=>`<button data-remove-type="${esc(type)}" data-remove-key="${esc(key)}" aria-label="Quitar filtro ${esc(ctx.label(type,key))}">${esc((layerNames[type]||type)+' '+key)}<span aria-hidden="true">×</span></button>`)).join('')}</div><label class="check filterPaint"><input id="paintEnabled" type="checkbox" ${enabled?'checked':''}> Mostrar colores en el plano</label>${plano==='architecture'?`<label for="activeLayer">Colorear y buscar por</label><select id="activeLayer">${families.map(([key,name])=>`<option value="${key}" ${key===active?'selected':''}>${name}</option>`).join('')}</select>`:''}<div class="filterCategoryHead"><h3>${esc(layerNames[active])}</h3><div><button id="marcarTodos" type="button">Todos</button><button id="marcarNinguno" type="button">Ninguno</button><button id="toggleCategorySearch" aria-controls="filterCategorySearch" aria-expanded="${!!categoryQuery}">Buscar</button></div></div><input id="filterCategorySearch" type="search" aria-label="Buscar categoría" placeholder="Código o descripción…" value="${esc(categoryQuery)}" ${categoryQuery?'':'hidden'}><div id="filterCategoryList">${distribution(ctx.all(),active).map(([key,n])=>`<div class="categoryControl" data-category-text="${esc(normalized(ctx.label(active,key)))}"><label><input type="checkbox" data-filter="${esc(key)}" ${ctx.marcada(active,key)?'checked':''}><span>${esc(ctx.label(active,key))}</span><b title="Recintos de este piso con esta categoría">${n}<small>${m2(sup.get(key))}</small></b></label><input type="color" aria-label="Color de ${esc(ctx.label(active,key))}" data-color="${esc(key)}" value="${categoryColor(active,key,colors)}"></div>`).join('')}</div><p id="noFilterCategories" hidden>Sin categorías coincidentes.</p><small class="filterHelp">Recintos y m² del piso completo.</small>${active==='PAV'&&ctx.retornos?.()?`<label class="check filterRetornos"><input type="checkbox" id="filterRetornos" ${ctx.verRetornos()?'checked':''}> Recintos con retorno · contorno magenta <b>${ctx.retornos().size}</b></label>`:''}${plano==='ceilings'&&ctx.originalesCielos?.()?'<button type="button" id="cielosOriginales">Láminas originales y registros</button>':''}</section>${seccionSobre()}<details class="filterMore" ${filters.asepsis?.length||filters.status?.length||filters.sector?.length?'open':''}><summary>Más filtros</summary><label for="asepsisAttribute">Asepsia documentada</label><select id="asepsisAttribute"><option value="">Todas / sin filtro</option>${distribution(ctx.all(),'asepsis').map(([key,n])=>`<option value="${esc(key)}" ${(filters.asepsis||[]).includes(key)?'selected':''}>${esc(key===UNKNOWN?'Clasificación no determinada':'Asepsia '+key)} · ${n}</option>`).join('')}</select>${[['status','Estado de revisión'],['sector','Sector']].map(([key,name])=>`<label for="filter-${key}">${name}</label><select id="filter-${key}" data-extra-filter="${key}"><option value="">Todos / sin filtro</option>${distribution(ctx.all(),key).map(([value,n])=>`<option value="${esc(value)}" ${(filters[key]||[]).includes(value)?'selected':''}>${esc(key==='sector'?'Sector '+value:value)} · ${n}</option>`).join('')}</select>`).join('')}</details><details class="filterMore"><summary>Colores y respaldo</summary><p id="layerColorNote">${note}</p><button id="resetLayerColors">Restablecer colores de esta capa</button><button id="filterBackup">Respaldar correcciones</button></details><p class="filterHelp">Los colores representan atributos documentados o estados registrados. No certifican ejecución ni superficies.</p></div><div class="planFilterFooter"><button id="clearPlanFilters">Limpiar todo</button><button id="applyPlanFilters" class="primary">Ver en el plano</button></div>`;
  root.querySelector('#closePlanFilters').onclick=()=>close(true);root.querySelector('#applyPlanFilters').onclick=()=>close(true);
  root.querySelectorAll('[data-tipo-plano]').forEach(b=>b.onclick=()=>{const tipo=b.dataset.tipoPlano,destino=tiposPlano().find(x=>x.dataset.planType===tipo),sale=!['architecture','walls'].includes(tipo);if(sale)close();destino?.click();if(!sale)setTimeout(render,60);});
  root.querySelectorAll('[data-capa]').forEach(i=>i.onchange=()=>ctx.mostrarCapa?.(i.dataset.capa,i.checked));
  root.querySelectorAll('[data-texto-plano]').forEach(i=>i.onchange=()=>{const original=document.getElementById(i.dataset.textoPlano);original.checked=i.checked;original.dispatchEvent(new Event('change'));});
  root.querySelector('#planFilterSearch').oninput=e=>ctx.search(e.target.value);
  root.querySelector('#paintEnabled').onchange=e=>ctx.change({enabled:e.target.checked},false);
  root.querySelector('#activeLayer')?.addEventListener('change',e=>{categoryQuery='';ctx.change({active:e.target.value,enabled:true});render();});
  root.querySelectorAll('[data-plano]').forEach(b=>b.onclick=()=>{const tipo=b.dataset.plano,antes=familiaDe(planoActual());if(antes)ctx.filter(antes,[]);const destino=tiposPlano().find(x=>x.dataset.planType===tipo);if(['doors','waterproofing'].includes(tipo))close();destino?.click();const fam=familiaDe(tipo);if(fam)ctx.change({active:fam,enabled:true});setTimeout(()=>{if(opened)render();},120);});
  root.querySelector('#cielosOriginales')?.addEventListener('click',()=>{const abrir=ctx.originalesCielos?.();close();abrir?.();});
  root.querySelector('#marcarTodos')?.addEventListener('click',()=>{ctx.marcarTodas(active);root.querySelectorAll('[data-filter]').forEach(i=>i.checked=true);});root.querySelector('#marcarNinguno')?.addEventListener('click',()=>{ctx.elegirCategorias(active,[]);root.querySelectorAll('[data-filter]').forEach(i=>i.checked=false);});root.querySelector('#filterRetornos')?.addEventListener('change',e=>ctx.mostrarRetornos(e.target.checked));
  root.querySelectorAll('[data-sobre]').forEach(i=>i.onchange=()=>{const fam=familiaDe(planoActual());ctx.change(i.checked?{active:i.dataset.sobre,enabled:true}:{active:fam||'walls',enabled:!!fam});render();});
  root.querySelector('#toggleCategorySearch').onclick=()=>{const input=root.querySelector('#filterCategorySearch');input.hidden=!input.hidden;root.querySelector('#toggleCategorySearch').setAttribute('aria-expanded',String(!input.hidden));if(!input.hidden)input.focus();else{categoryQuery='';input.value='';searchCategories();}};
  root.querySelector('#filterCategorySearch').oninput=e=>{categoryQuery=e.target.value;searchCategories();};
  root.querySelectorAll('[data-filter]').forEach(input=>input.onchange=()=>ctx.elegirCategorias(active,[...root.querySelectorAll('[data-filter]:checked')].map(n=>n.dataset.filter)));
  root.querySelectorAll('[data-remove-type]').forEach(b=>b.onclick=()=>{ctx.filter(b.dataset.removeType,(ctx.state().filters[b.dataset.removeType]||[]).filter(k=>k!==b.dataset.removeKey));render();});
  
  root.querySelector('#asepsisAttribute').onchange=e=>{ctx.filter('asepsis',e.target.value?[e.target.value]:[]);render();};
  root.querySelectorAll('[data-extra-filter]').forEach(input=>input.onchange=()=>{ctx.filter(input.dataset.extraFilter,input.value?[input.value]:[]);render();});
  root.querySelectorAll('[data-color]').forEach(input=>input.oninput=()=>{ctx.color(active,input.dataset.color,input.value);});
  root.querySelector('#resetLayerColors').onclick=()=>{ctx.resetColors(active);render();};
  root.querySelector('#clearPlanFilters').onclick=()=>{categoryQuery='';ctx.reset();render();};root.querySelector('#filterBackup').onclick=()=>document.getElementById('import').click();
  root.querySelector('.planFilterBody').scrollTop=scroll;root.scrollTop=scrollHoja;searchCategories();update();const next=focusKey?[...root.querySelectorAll('[data-filter]')].find(input=>input.dataset.filter===focusKey):focusId?[...root.querySelectorAll('[id]')].find(node=>node.id===focusId):null;next?.focus({preventScroll:true});
 }
 function searchCategories(){const query=normalized(categoryQuery.trim());let n=0;root.querySelectorAll('[data-category-text]').forEach(row=>{row.hidden=!row.dataset.categoryText.includes(query);if(!row.hidden)n++;});root.querySelector('#noFilterCategories').hidden=!!n;}
 button.onclick=()=>opened?close(true):open();
 window.addEventListener('atlas-plano-cambiado',()=>{if(opened)render();});
 root.addEventListener('keydown',event=>{if(event.key==='Escape'){event.stopPropagation();close(true);}});
 window.addEventListener('atlas-floor-home',()=>close());
 return {open,close,update,isOpen:()=>opened};
}
